    /// <summary>Gets CodeBase's Spanish cp850 table.</summary>
    public static ReadOnlySpan<byte> SpanishCp850 => SpanishCp850Data;

    /// <summary>Gets Visual FoxPro's GENERAL table for a code page CodeBase has none for, or nothing.</summary>
    /// <param name="codePage">The code page.</param>
    /// <returns>The table, or an empty span for a code page VFP has no GENERAL on.</returns>
    public static ReadOnlySpan<byte> VisualFoxProGeneral(int codePage) => codePage switch
    {
        620 => VfpGeneral620Data,
        850 => VfpGeneral850Data,
        852 => VfpGeneral852Data,
        857 => VfpGeneral857Data,
        861 => VfpGeneral861Data,
        865 => VfpGeneral865Data,
        895 => VfpGeneral895Data,
        1250 => VfpGeneral1250Data,
        1254 => VfpGeneral1254Data,
        10000 => VfpGeneral10000Data,
        10029 => VfpGeneral10029Data,
        _ => [],
    };

    /// <summary>Gets the expansions of Visual FoxPro's GENERAL on a code page CodeBase has none for.</summary>
    /// <param name="codePage">The code page.</param>
    /// <returns>The expansions, or an empty span.</returns>
    public static ReadOnlySpan<byte> VisualFoxProGeneralExpansions(int codePage) => codePage switch
    {
        620 => VfpGeneral620ExpansionData,
        850 => VfpGeneral850ExpansionData,
        852 => VfpGeneral852ExpansionData,
        857 => VfpGeneral857ExpansionData,
        861 => VfpGeneral861ExpansionData,
        865 => VfpGeneral865ExpansionData,
        895 => VfpGeneral895ExpansionData,
        1250 => VfpGeneral1250ExpansionData,
        1254 => VfpGeneral1254ExpansionData,
        10000 => VfpGeneral10000ExpansionData,
        10029 => VfpGeneral10029ExpansionData,
        _ => [],
    };

    /// <summary>The weights of one of Visual FoxPro's named collations on one code page.</summary>
    /// <param name="Table">One head and one tail per byte value.</param>
    /// <param name="Expansions">Two bytes per expansion.</param>
    /// <param name="Sequences">Eight bytes per sequence: its length, three bytes, two heads, two tails; 0xFF for none.</param>
    internal sealed record NamedWeights(byte[] Table, byte[] Expansions, byte[] Sequences);

    /// <summary>Gets Visual FoxPro's weights for a named collation on a code page, or null where VFP has none.</summary>
    /// <param name="collation">The collation.</param>
    /// <param name="codePage">The code page.</param>
    /// <returns>The weights, recovered from VFP's keys (ADR-87), or null.</returns>
    public static NamedWeights? VisualFoxProNamed(CollationName collation, int codePage) =>
        Named.TryGetValue((collation, codePage), out NamedWeights? weights) ? weights : null;

